mapper.select:
SELECT csa.animal_cage_id AS animalCageId, csa.status_code AS statusCode, csa.started_at AS startedAt, csa.fired_at AS firedAt, csa.threshold_days AS thresholdDays, csa.action AS action, cci.shelve_id AS shelveId, si.room_id AS roomId FROM cage_status_alert csa LEFT JOIN cage_cell_index cci ON cci.animal_cage_id = csa.animal_cage_id LEFT JOIN cage_shelf_index si ON si.id = cci.shelf_index_id WHERE csa.state = 'ACTIVE'
AND csa.animal_cage_id IN #{cid}
ORDER BY csa.fired_at DESC
